workspace "Claims Center" "C4 model of the insurance claims platform" {

    !identifiers hierarchical

    model {

        policyholder = person "Policyholder" "Reports claims and tracks their progress"

        claimsCenter = softwareSystem "Claims Center" "The insurance company's claims platform" {

            webPortal = container "Web Portal" "Where policyholders report claims and track their progress" "Web application" "Web"
            mobileAppBackend = container "Mobile App Backend" "Serves the insurer's mobile app" "API service"
            claimsIntake = container "Claims Intake Service" "Registers new claims" "Service"
            triage = container "Triage Service" "Classifies and prioritizes claims" "Service"
            assessment = container "Assessment Service" "Calculates settlement amounts" "Service"
            payout = container "Payout Service" "Executes claim settlements" "Service"
            fraudScreening = container "Fraud Screening Service" "Flags suspicious claims" "Service"
            documentService = container "Document Service" "Accepts claim photos and reports" "Service"
            notification = container "Notification Service" "Emails and messages policyholders" "Service"
            assignment = container "Assignment Service" "Routes claims to adjusters" "Service"
            adjusterWorkbench = container "Adjuster Workbench" "Where staff process their assigned claims" "Web application" "Web"
            policyVerification = container "Policy Verification Service" "Checks that a claim is covered by the policy" "Service"
            reinsuranceAllocation = container "Reinsurance Allocation Service" "Apportions large losses across reinsurance partners" "Service"
            batchScheduler = container "Batch Scheduler" "Runs the nightly reserves calculation" "Batch job"
            eventQueue = container "Event Queue" "Carries claim events between the application parts" "Message queue" "Queue"
            claimsDb = container "Claims Database" "Stores claim records" "Database" "Database"
            policyDb = container "Policy Database" "Stores policy and cover records" "Database" "Database"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Database" "Database"
            documentStore = container "Document Store" "Holds claim photos, reports, and correspondence" "Object storage" "Database"
        }

        nationalBureau = softwareSystem "National Claims Data Bureau" "Operated by a different organization" "External"
        clearingHouse = softwareSystem "Clearing House" "Operated by a different organization" "External"

        policyholder -> claimsCenter.webPortal "reports claims and tracks progress" "HTTPS"
        policyholder -> claimsCenter.mobileAppBackend "reports claims and tracks progress via the insurer's mobile app" "HTTPS"

        claimsCenter.webPortal -> claimsCenter.claimsIntake "submits new claims to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.documentService "uploads claim photos and reports to" "HTTPS"
        claimsCenter.webPortal -> claimsCenter.notification "requests claim status updates from" "HTTPS"

        claimsCenter.mobileAppBackend -> claimsCenter.claimsIntake "submits new claims to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.assessment "requests settlement amounts from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.payout "requests settlements from" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.documentService "uploads claim photos and reports to" "HTTPS"
        claimsCenter.mobileAppBackend -> claimsCenter.notification "requests claim status updates from" "HTTPS"

        claimsCenter.claimsIntake -> claimsCenter.triage "hands accepted claims to" "HTTPS"
        claimsCenter.triage -> claimsCenter.assessment "routes claims to" "HTTPS"
        claimsCenter.assessment -> claimsCenter.payout "requests settlements from" "HTTPS"

        claimsCenter.fraudScreening -> nationalBureau "consults for claim history" "HTTPS"
        claimsCenter.payout -> clearingHouse "executes settlements through" "HTTPS"

        claimsCenter.assignment -> claimsCenter.adjusterWorkbench "routes claims to" "HTTPS"
        claimsCenter.policyVerification -> claimsCenter.policyDb "checks cover against" "SQL"

        claimsCenter.documentService -> claimsCenter.documentStore "reads from" "TCP"
        claimsCenter.batchScheduler -> claimsCenter.claimsDb "reads and writes" "SQL"
        claimsCenter.batchScheduler -> claimsCenter.policyDb "reads and writes" "SQL"

        claimsCenter.notification -> policyholder "reports claim status changes via email and message" "Email, SMS"
    }

    views {
        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }

        container claimsCenter "Containers" {
            include *
            autoLayout
            title "Containers for Claims Center"
        }

        styles {
            element "Person" {
                shape Person
                background #08427B
                color #ffffff
            }
            element "Software System" {
                background #1168BD
                color #ffffff
            }
            element "External" {
                background #999999
                color #ffffff
            }
            element "Container" {
                background #438DD5
                color #ffffff
            }
            element "Database" {
                shape Cylinder
            }
            element "Web" {
                shape WebBrowser
            }
            element "Queue" {
                shape Pipe
            }
        }
    }
}

