// Test candidate inspection property names to see which suppress the errors.
const base = (props, scope) => `workspace "Claims Center" "C4 model of the insurance claims platform" {

    !identifiers hierarchical

    model {
${props}
        policyholder = person "Policyholder" "Reports claims and tracks their progress"
        claimsCenter = softwareSystem "Claims Center" "The insurance company's claims platform" {
            reinsuranceAllocation = container "Reinsurance Allocation Service" "Apportions large losses across reinsurance partners" "Service"
            eventQueue = container "Event Queue" "Carries claim events between the application parts" "Message queue" "Queue"
            auditDb = container "Audit Database" "Stores the compliance audit trail" "Database" "Database"
        }
        nationalBureau = softwareSystem "National Claims Data Bureau" "Operated by a different organization" "External"
        claimsCenter.reinsuranceAllocation -> nationalBureau "apportions losses to" "HTTPS"
    }

    views {
        systemContext claimsCenter "SystemContext" {
            include *
            autoLayout
            title "System Context for Claims Center"
        }
    }
${scope ? `
    configuration {
        scope ${scope}
    }
